'use strict';
const H={};
const p={"torque":1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 写出两自由度单输入系统
Object.assign(s, ((s,p)=>({mass:[[2,1],[1,2]],input:[0,p.torque],configurationDof:2,actuatorRank:1}))(s, p));
// 用输入矩阵判断欠驱动
Object.assign(s, ((s,p)=>({underactuated:s.actuatorRank<s.configurationDof}))(s, p));
// 耦合质量矩阵使未驱动关节也加速
Object.assign(s, ((s,p)=>({acceleration:[-p.torque/3,2*p.torque/3]}))(s, p));
// 回代动力学核对
Object.assign(s, ((s,p)=>({recoveredForce:[2*s.acceleration[0]+s.acceleration[1],s.acceleration[0]+2*s.acceleration[1]]}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"angle":60,"velocity":0,"torque":0};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 先确定角度零点
Object.assign(s, ((s,p)=>({theta:p.angle*Math.PI/180,omega:p.velocity}))(s, p));
// 由力矩平衡求加速度
Object.assign(s, ((s,p)=>({acceleration:p.torque-.1*s.omega-9.81*Math.sin(s.theta)}))(s, p));
// 计算相空间中的速度向量
Object.assign(s, ((s,p)=>({stateDerivative:[s.omega,s.acceleration]}))(s, p));
// 算机械能并保留势能零点
Object.assign(s, ((s,p)=>({energy:.5*s.omega*s.omega+9.81*(1-Math.cos(s.theta))}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"deviation":0.1,"gain":12};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 围绕向上平衡点定义小量
Object.assign(s, ((s,p)=>({delta:p.deviation,gravity:9.81}))(s, p));
// 比较非线性与线性重力项
Object.assign(s, ((s,p)=>({nonlinear:s.gravity*Math.sin(s.delta),linear:s.gravity*s.delta}))(s, p));
// 加入位置负反馈
Object.assign(s, ((s,p)=>({control:-p.gain*s.delta,positionCoefficient:s.gravity-p.gain}))(s, p));
// 区分恢复力与渐近稳定
Object.assign(s, ((s,p)=>({linearAcceleration:s.positionCoefficient*s.delta,restoring:p.gain>s.gravity,approximationError:s.nonlinear-s.linear}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"a":1.1,"r":1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 固定有限时域标量系统
Object.assign(s, ((s,p)=>({q:1,terminal:1,horizon:3}))(s, p));
// 反向Riccati递推
Object.assign(s, ((s,p)=>{let P=s.terminal;const backwards=[];for(let k=2;k>=0;k--){const K=p.a*P/(p.r+P),next=1+p.a*p.a*P-p.a*p.a*P*P/(p.r+P);backwards.push({k,Pnext:P,K,P:next});P=next;}return {backwards,initialP:P};})(s, p));
// 提取最初一步反馈
Object.assign(s, ((s,p)=>({gain:s.backwards[s.backwards.length-1].K}))(s, p));
// 从x=1执行第一步
Object.assign(s, ((s,p)=>({control:-s.gain,nextState:p.a-s.gain}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"x":1,"limit":1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 给出非线性一维系统
Object.assign(s, ((s,p)=>({state:p.x,derivative:-p.x+p.x**3}))(s, p));
// 沿动力学求Vdot
Object.assign(s, ((s,p)=>({value:p.x*p.x/2,valueDerivative:p.x*s.derivative}))(s, p));
// 比较单点检查与区域符号
Object.assign(s, ((s,p)=>({pointDecreasing:s.valueDerivative<0,strictDomain:p.limit<1}))(s, p));
// 陈述可支持的结论
Object.assign(s, ((s,p)=>({insideCertifiedRegion:Math.abs(p.x)<1,atTargetEquilibrium:p.x===0,atEquilibrium:Math.abs(s.derivative)<1e-12}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={clamp:(x,a,b)=>Math.max(a,Math.min(b,x))};
const p={"angle":90,"velocity":1,"limit":2};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 计算当前能量和向上目标能量
Object.assign(s, ((s,p)=>({theta:p.angle*Math.PI/180,energy:.5*p.velocity*p.velocity+9.81*(1-Math.cos(p.angle*Math.PI/180)),desired:19.62}))(s, p));
// 用能量差决定注入方向
Object.assign(s, ((s,p)=>({rawTorque:.5*(s.desired-s.energy)*p.velocity}))(s, p));
// 施加执行器饱和
Object.assign(s, ((s,p)=>({torque:H.clamp(s.rawTorque,-p.limit,p.limit)}))(s, p));
// 检查能量变化率和静止盲点
Object.assign(s, ((s,p)=>({energyRate:s.torque*p.velocity,energyError:s.desired-s.energy,stalled:p.velocity===0}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"middle":0.5,"control":1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 把连续问题变成节点与约束
Object.assign(s, ((s,p)=>({states:[0,p.middle,1],dt:.5,controls:[p.control,p.control,p.control]}))(s, p));
// 计算梯形离散的动力学缺陷
Object.assign(s, ((s,p)=>({defects:[p.middle-.5*p.control,1-p.middle-.5*p.control]}))(s, p));
// 积分控制代价
Object.assign(s, ((s,p)=>({cost:p.control*p.control}))(s, p));
// 同时核对边界与缺陷
Object.assign(s, ((s,p)=>({maxDefect:Math.max(...s.defects.map(Math.abs)),discreteFeasible:s.defects.every(x=>Math.abs(x)<1e-9)}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"state":1,"disturbance":0.25};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 给出候选输入和预测模型
Object.assign(s, ((s,p)=>({actions:[-1,0,1]}))(s, p));
// 只用模型选择当前动作
Object.assign(s, ((s,p)=>({costs:s.actions.map(u=>(p.state+u)**2+.1*u*u)}))(s, p));
// 执行第一动作并测量新状态
Object.assign(s, ((s,p)=>{const best=s.costs.indexOf(Math.min(...s.costs)),u=s.actions[best];return {action:u,predicted:p.state+u,measured:p.state+u+p.disturbance};})(s, p));
// 基于新测量重新规划
Object.assign(s, ((s,p)=>({nextCosts:s.actions.map(u=>(s.measured+u)**2+.1*u*u),predictionError:s.measured-s.predicted}))(s, p));
console.log(JSON.stringify(s,null,2));
